  registerHandler('get-settings', async () => {
    console.log('[Settings] get-settings called');
    const settings = loadSettings();
    const syncState = loadListSyncState();
    if (!listSyncPullAttempted && settings?.listSyncEnabled) {
      listSyncPullAttempted = true;
      const pull = await syncListsFromGitHub(settings);
      if (!pull.ok) {
        updateListSyncState({
          lastAttemptAt: Date.now(),
          lastError: pull.error || 'GitHub pull failed',
        });
      }
    }
    if (settings?.listSyncEnabled && syncState?.pendingPush) {
      const push = await syncListsToGitHub(settings);
      updateListSyncState({
        pendingPush: !push.ok,
        lastAttemptAt: Date.now(),
        lastError: push.ok ? '' : (push.error || 'GitHub push retry failed'),
        lastSyncAt: push.ok ? Date.now() : syncState?.lastSyncAt,
      });
    }
    const backendBaseUrl = String(settings?.backendBaseUrl || process.env.MOSSY_BACKEND_URL || 'https://mossy.onrender.com').trim();
    const backendTokenConfigured = Boolean(getSecretValue(settings, 'backendToken', 'MOSSY_BACKEND_TOKEN'));
    const githubTokenConfigured = Boolean(getSecretValue(settings, 'githubToken', 'GITHUB_TOKEN'));
    // Added 2026-08-26 (API-key-confirmation-dialog fix): the AI Chat cloud
    // path (LocalAIEngine.ts) used to show a "Mossy is about to use a cloud
    // AI provider (your configured API key)" confirm() dialog before EVERY
    // cloud call whenever the "Require Key Confirmation" privacy toggle was
    // on -- including the default zero-config path, where ai-chat-groq
    // actually goes through the bundled Render backend (mossy.onrender.com)
    // using Mossy's own server-side key, not anything the user configured.
    // getBackendConfig() in this file falls back to that Render URL even
    // with no env var set, so it's non-null for virtually every install --
    // "your configured API key" was simply false for almost everyone who
    // saw that dialog. This flag tells the renderer whether a call will
    // actually spend a key the user personally supplied: either an Inkling
    // key (always tried first, unconditionally) or a direct Groq key used
    // only when no backend is configured at all (an explicit self-hosted/
    // advanced setup). The renderer now only shows the confirmation when
    // this is true, so the default Render-backend flow never prompts.
    const usesOwnCloudApiKey = Boolean(getSecretValue(settings, 'inklingApiKey', 'INKLING_API_KEY'))
      || (!getBackendConfig() && Boolean(getSecretValue(settings, 'groqApiKey', 'GROQ_API_KEY')));
    return redactSettingsForRenderer({
      ...settings,
      backendBaseUrl,
      backendTokenConfigured,
      githubTokenConfigured,
      usesOwnCloudApiKey,
    });
  });

  // Live bridge connection info for the renderer's HTTP calls to BridgeServer.ts.
  // Port is ephemeral (OS-assigned) and only known after bridge.start()'s listen
  // callback fires, so this can't just be baked into settings.json like the
  // token — it has to be queried live. See BridgeServer.ts's class-level
  // SECURITY comment for why both of these exist at all.
  registerHandler('get-bridge-connection', async () => {
    const settings = loadSettings();
    return { port: bridge.getPort(), token: String(settings?.bridgeAuthToken || '') };
  });

  registerHandler('set-settings', async (_event, newSettings: any) => {
    try {
      console.log('[Settings] set-settings called with keys:', Object.keys(newSettings || {}));
    } catch {
      console.log('[Settings] set-settings called');
    }
    const current = loadSettings();

    // Strip *Enc fields from renderer input before merging. The renderer must never
    // be able to directly inject pre-computed encrypted values — all secret fields
    // must go through encryptSecretForStorage() in this process.
    const sanitizedInput: any = { ...(newSettings || {}) };
    const fields: SecretField[] = ['openaiApiKey', 'groqApiKey', 'backendToken', 'githubToken', 'inklingApiKey'];
    for (const field of fields) {
      delete sanitizedInput[secretEncKey(field)];
    }

    const updated = { ...current, ...sanitizedInput };
    const beforeLists = JSON.stringify(buildListsPayloadFromSettings(current));

    // Never persist plaintext secrets. If renderer provides them, encrypt into *Enc fields.
    // If the renderer sends an empty string (redacted value), preserve the existing encrypted key.
    const next: any = { ...updated };
    for (const field of fields) {
      if (!hasOwn(sanitizedInput, field)) continue;
      const encKey = secretEncKey(field);
      const plain = String(sanitizedInput[field] || '').trim();
      if (!plain) {
        // Renderer sent empty (key was redacted) — keep existing encrypted value, clear any stray plaintext.
        next[field] = '';
        continue;
      }
      next[encKey] = encryptSecretForStorage(plain);
      next[field] = '';
      // Real timestamp for "Enable API Key Rotation" — lets the UI honestly
      // warn when a key is older than securitySettings.apiKeyRotationDays,
      // rather than the toggle existing but nothing ever tracking key age.
      next.apiKeySetAt = { ...(current?.apiKeySetAt || {}), [field]: Date.now() };
    }

    // The renderer's copy of privacySettings never contains the password
    // hash/salt (redacted by redactSettingsForRenderer) — if we naively took
    // whatever it sends, saving any unrelated toggle would silently erase a
    // previously-set app-lock password. Only security:set-password /
    // security:clear-password (below) may change these two fields.
    if (next.privacySettings) {
      next.privacySettings.settingsPasswordHash = current?.privacySettings?.settingsPasswordHash;
      next.privacySettings.settingsPasswordSalt = current?.privacySettings?.settingsPasswordSalt;
      delete next.privacySettings.hasSettingsPassword; // synthetic renderer-only field — never persisted
    }

    migrateMemoryStorageIfNeeded(current, next);
    saveSettings(next);

    const afterLists = JSON.stringify(buildListsPayloadFromSettings(next));
    if (beforeLists !== afterLists) {
      const push = await syncListsToGitHub(next);
      updateListSyncState({
        lastAttemptAt: Date.now(),
        lastError: push.ok ? '' : (push.error || 'GitHub push failed'),
        lastSyncAt: push.ok ? Date.now() : undefined,
        pendingPush: !push.ok,
      });
      if (push.ok) {
        const refreshed = { ...next, listSyncLastSyncAt: Date.now(), listSyncLastError: '' };
        saveSettings(refreshed);
      } else {
        const refreshed = { ...next, listSyncLastError: push.error || 'GitHub push failed' };
        saveSettings(refreshed);
      }
    }
    return;
  });

  /**
   * App-lock password management — backs both "Require Password for
   * Settings" and "Auto-Lock After Inactivity". Only a salted scrypt hash is
   * ever persisted (never the plaintext), and these are the only handlers
   * allowed to touch privacySettings.settingsPasswordHash/-Salt (see the
   * guard added in set-settings above).
   */
  registerHandler('security:has-password', async () => {
    const s = loadSettings();
    return { hasPassword: !!s?.privacySettings?.settingsPasswordHash };
  });

  registerHandler('security:set-password', async (_event, params: { password: string }) => {
    try {
      const password = String(params?.password || '');
      if (password.length < 4) {
        return { success: false, error: 'Password must be at least 4 characters.' };
      }
      const salt = crypto.randomBytes(16).toString('hex');
      const hash = crypto.scryptSync(password, salt, 64).toString('hex');
      const current = loadSettings();
      saveSettings({
        ...current,
        privacySettings: {
          ...current.privacySettings,
          settingsPasswordHash: hash,
          settingsPasswordSalt: salt,
        },
      });
      return { success: true };
    } catch (error: any) {
      return { success: false, error: error?.message || String(error) };
    }
  });

  registerHandler('security:clear-password', async () => {
    const current = loadSettings();
    saveSettings({
      ...current,
      privacySettings: {
        ...current.privacySettings,
        settingsPasswordHash: undefined,
        settingsPasswordSalt: undefined,
        // Both features require a password to function — turn them off too
        // rather than leaving them enabled with nothing to check against.
        requirePasswordForSettings: false,
        autoLockAfterInactivity: false,
      },
    });
    return { success: true };
  });

  registerHandler('security:verify-password', async (_event, params: { password: string }) => {
    try {
      const s = loadSettings();
      const storedHash = s?.privacySettings?.settingsPasswordHash;
      const salt = s?.privacySettings?.settingsPasswordSalt;
      if (!storedHash || !salt) return { valid: false, error: 'No password is set.' };

      const attemptHash = crypto.scryptSync(String(params?.password || ''), salt, 64).toString('hex');
      const a = Buffer.from(attemptHash, 'hex');
      const b = Buffer.from(storedHash, 'hex');
      const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
      return { valid };
    } catch (error: any) {
      return { valid: false, error: error?.message || String(error) };
    }
  });

  registerHandler('list-sync:get-status', async () => {
    const settings = loadSettings();
    const state = loadListSyncState();
    return {
      enabled: !!settings?.listSyncEnabled,
      repo: settings?.listSyncRepo || settings?.communityRepo || '',
      branch: settings?.listSyncBranch || 'main',
      lastSyncAt: settings?.listSyncLastSyncAt || state?.lastSyncAt,
      lastError: settings?.listSyncLastError || state?.lastError || '',
      pendingPush: !!state?.pendingPush,
    };
  });

  registerHandler('list-sync:sync-now', async () => {
    const settings = loadSettings();
    const pull = await syncListsFromGitHub(settings);
    const refreshed = loadSettings();
    const push = await syncListsToGitHub(refreshed);
    const ok = pull.ok && push.ok;
    updateListSyncState({
      lastAttemptAt: Date.now(),
      lastError: ok ? '' : [pull.error, push.error].filter(Boolean).join(' | '),
      lastSyncAt: ok ? Date.now() : undefined,
      pendingPush: !ok,
    });
    if (ok) {
      saveSettings({ ...refreshed, listSyncLastSyncAt: Date.now(), listSyncLastError: '' });
    } else {
      saveSettings({ ...refreshed, listSyncLastError: [pull.error, push.error].filter(Boolean).join(' | ') });
    }
    return { ok, pull, push };
  });

