  // --- Proactive Observer (Neural Link+) ---
  registerHandler(IPC_CHANNELS.OBSERVER_SET_ACTIVE_FOLDER, async (_event, folderPath: string) => {
    try {
      if (activeWatcher) {
        activeWatcher.close();
        activeWatcher = null;
      }

      if (!folderPath || !fs.existsSync(folderPath)) {
        activeProjectFolder = null;
        return { ok: true, monitoring: false };
      }

      activeProjectFolder = folderPath;
      console.log('[Observer] Starting proactive watcher on:', folderPath);

      // Simple implementation using fs.watch
      activeWatcher = fs.watch(folderPath, { recursive: true }, (eventType, filename) => {
        if (!filename) return;

        const fullPath = path.join(activeProjectFolder!, filename);

        // Anti-flap / debounce
        const now = Date.now();
        if (lastAnalyzedFile === fullPath && now - lastAnalysisTime < 2000) return;

        // Triggers on creation or change of interesting files
        if (eventType === 'rename' || eventType === 'change') {
          if (fs.existsSync(fullPath)) {
            const ext = path.extname(filename).toLowerCase();

            // Logic for automated auditing
            if (ext === '.nif' || ext === '.dds' || ext === '.esp') {
              console.log(`[Observer] Auto-detecting change: ${filename}`);
              lastAnalyzedFile = fullPath;
              lastAnalysisTime = now;

              notifyObserver('file-detected', {
                filename,
                fullPath,
                type: ext.substring(1)
              });

              // Automate audit if desired
              // In a real implementation, we would call the audit logic here
              // and send the result in a second notification.
            }
          }
        }
      });

      return { ok: true, monitoring: true, folder: folderPath };
    } catch (e: any) {
      console.error('[Observer] Error starting watcher:', e);
      return { ok: false, error: String(e?.message || e) };
    }
  });

  // Desktop Bridge: check Blender Mossy Link add-on socket
  registerHandler('check-blender-addon', async () => {
    try {
      const net = await import('net');
      return await new Promise<{ connected: boolean; error?: string }>((resolve) => {
        const socket = new net.Socket();
        const timeoutMs = 500;
        const cleanup = () => {
          try { socket.destroy(); } catch { /* ignore */ }
        };

        socket.setTimeout(timeoutMs);

        socket.once('connect', () => {
          cleanup();
          resolve({ connected: true });
        });
        socket.once('timeout', () => {
          cleanup();
          resolve({ connected: false, error: 'timeout' });
        });
        socket.once('error', (err: any) => {
          cleanup();
          resolve({ connected: false, error: String(err?.message || err) });
        });

        try {
          socket.connect(9999, '127.0.0.1');
        } catch (e: any) {
          cleanup();
          resolve({ connected: false, error: String(e?.message || e) });
        }
      });
    } catch (e: any) {
      return { connected: false, error: String(e?.message || e) };
    }
  });

  // Track if we've already sent PyTorch path to Blender in this session
  let _blenderPytorchPathSent = false;

  /**
   * Helper to send a single command to Blender's TCP server
   */
  const _sendToBlenderTCP = async (payload: any): Promise<any> => {
    const net = await import('net');
    return new Promise((resolve) => {
      const socket = new net.Socket();
      const timeoutMs = 10000;
      let responseReceived = false;

      const cleanup = () => {
        try { socket.destroy(); } catch { /* ignore */ }
      };

      socket.setTimeout(timeoutMs);

      socket.on('connect', () => {
        socket.write(JSON.stringify(payload));
      });

      socket.on('data', (data) => {
        if (responseReceived) return;
        responseReceived = true;

        try {
          const response = JSON.parse(data.toString().trim());
          cleanup();

          const normalizedSuccess = typeof response.success === 'boolean'
            ? response.success
            : response.status === 'success';

          const standardResponse = {
            success: normalizedSuccess,
            status: response.status || (normalizedSuccess ? 'success' : 'error'),
            message: response.message || response.error || '',
            ...response
          };

          resolve(standardResponse);
        } catch (e) {
          cleanup();
          resolve({ success: false, status: 'error', message: 'Invalid JSON response from Blender addon' });
        }
      });

      socket.on('timeout', () => {
        if (!responseReceived) {
          cleanup();
          resolve({ success: false, status: 'error', message: 'Timeout waiting for Blender response' });
        }
      });

      socket.on('error', (err: any) => {
        if (!responseReceived) {
          cleanup();
          resolve({ success: false, status: 'error', message: String(err?.message || err) });
        }
      });

      socket.on('close', () => {
        if (!responseReceived) {
          resolve({ success: false, status: 'error', message: 'Connection closed by Blender addon' });
        }
      });

      try {
        socket.connect(9999, '127.0.0.1');
      } catch (e: any) {
        cleanup();
        resolve({ success: false, status: 'error', message: String(e?.message || e) });
      }
    });
  };

  /**
   * send-blender-command - Uses the exact Blender Bridge protocol
   * 
   * Sends a command to the Blender add-on (mossy_link.py) on port 9999.
   * Auto-sends PyTorch path on first connection.
   * Protocol matches the official Blender-add-on:
   * - Command types: "script", "text", "get_capabilities", "query_mossy", "call_tool"
   * - Request: { type, code?, name?, run?, query?, context?, tool?, action?, payload?, token? }
   * - Response: { status, message?, ... }
   * 
   * @param _event - IPC event
   * @param commandType - Command type: "script", "text", "get_capabilities", etc.
   * @param commandData - Command payload (varies by type)
   * @param token - Optional authentication token (matches prefs.token in Blender)
   */
  registerHandler('send-blender-command', async (_event, commandType: string, commandData: any = {}, token?: string) => {
    try {
      // AUTO-SEND PYTORCH PATH ON FIRST BLENDER COMMAND
      if (!_blenderPytorchPathSent) {
        const s = loadSettings();
        const pytorchPath = s?.pytorchPath as string | undefined;

        if (pytorchPath) {
          console.log('[Blender Bridge] PyTorch path in settings:', pytorchPath);
          if (fs.existsSync(pytorchPath)) {
            try {
              console.log('[Blender Bridge] ✅ PyTorch path exists, auto-sending to Blender on first connection...');
              // mossy_link.py's _handle_connection rejects any command whose
              // token doesn't match the configured Blender-side token (fail-closed
              // auth) — this payload was missing that field, so this auto-send
              // silently got "Unauthorized" from Blender every time a token was
              // configured (the token IS configured by default — see line ~1750).
              const pathPayload: any = { type: 'set_pytorch_path', path: pytorchPath };
              if (s?.blenderLinkToken) {
                pathPayload.token = s.blenderLinkToken;
              }
              const pathResult = await _sendToBlenderTCP(pathPayload);
              console.log('[Blender Bridge] PyTorch auto-send result:', pathResult.status, '-', pathResult.message);
              _blenderPytorchPathSent = true;
            } catch (e: any) {
              console.warn('[Blender Bridge] ⚠️ Failed to send PyTorch path:', e?.message);
            }
          } else {
            console.warn('[Blender Bridge] ⚠️ PyTorch path does not exist:', pytorchPath);
          }
        } else {
          console.log('[Blender Bridge] PyTorch path not configured. Skipping auto-send.');
        }
      }

      // Build the exact JSON format that mossy_link.py expects
      const payload: any = { type: commandType };

      // Merge command-specific fields
      if (commandType === 'script' || commandType === 'text') {
        payload.code = commandData.code || '';
        if (commandType === 'text') {
          payload.name = commandData.name || 'MOSSY_SCRIPT';
          payload.run = Boolean(commandData.run);
        }
      } else if (commandType === 'execute_script') {
        // MossyTools.ts's executeMossyTool() sends { script } under this commandType,
        // but the Blender add-on's real wire protocol only knows "script" — translate.
        payload.type = 'script';
        payload.code = commandData.script || commandData.code || '';
      } else if (commandType === 'query_mossy') {
        payload.query = commandData.query || '';
        payload.context = commandData.context || '';
      } else if (commandType === 'call_tool') {
        payload.tool = commandData.tool || '';
        payload.action = commandData.action || '';
        payload.payload = commandData.payload || {};
      } else if (commandType === 'pytorch_inference') {
        payload.model = commandData.model || '';
        payload.image_path = commandData.imagePath || '';
        payload.output_path = commandData.outputPath || '';
      } else if (commandType === 'run_automation') {
        // 'run_automation' (and 'call_tool'/'query_mossy'/'pytorch_inference' above) were
        // command types the now-retired public/mossy_link_addon.py supported. The add-on
        // this converged onto (POINTYTHRUNDRA654/Blender-add-on's mossy_link.py — see
        // ARCHITECTURE.md's "Bridge auth" section) never implemented any of these; it
        // exposes equivalent FO4 automation through named Blender operators via the
        // 'operator' command type instead. DesktopBridge.tsx's automation buttons
        // (sendBlenderCommandWithToken('run_automation', ...) / ('call_tool', ...)) will
        // get "Unknown command type" from the real add-on until those buttons are ported
        // to 'operator' calls against real operator ids — not done yet, flagged rather
        // than guessed at, since that requires knowing the other repo's actual operator
        // surface.
        payload.preset = commandData.preset || '';
        payload.params = commandData.params || {};
      }

      // Add token if provided
      if (token) {
        payload.token = token;
      }

      // Use the helper to send the command
      return await _sendToBlenderTCP(payload);
    } catch (e: any) {
      return { success: false, status: 'error', message: String(e?.message || e) };
    }
  });

  /**
   * AnimationEditor.tsx: real .nif skeleton load/save.
   *
   * Rather than hand-rolling a NIF binary parser (Bethesda's NIF header/block layout is
   * version-conditional in ways that are easy to get subtly wrong, and a wrong byte offset
   * would silently produce garbage bone data or corrupt a real save), this routes through
   * the already-real, already-connected Mossy Link Blender bridge and PyNifly — the actual
   * tool the FO4 modding community uses for NIF I/O — the same way run_automation/execute_script
   * already do. Requires the user to have Blender open with Mossy Link v6 connected.
   */
  registerHandler('animation-editor:load-nif', async (_event, nifPath: string) => {
    try {
      if (!nifPath || !fs.existsSync(nifPath)) {
        return { success: false, error: 'NIF file not found on disk.' };
      }
      const escapedPath = nifPath.replace(/\\/g, '\\\\');
      const code = [
        'import json',
        'import math',
        'result = {"success": False, "bones": [], "error": None}',
        'try:',
        "    if not (hasattr(bpy.ops, 'import_scene') and hasattr(bpy.ops.import_scene, 'pynifly')):",
        '        result["error"] = "PyNifly is not installed in this Blender. Install PyNifly 25+ (Nexus #52319) for Blender 4.4+."',
        '    else:',
        '        before = set(o.name for o in bpy.data.objects)',
        `        bpy.ops.import_scene.pynifly(filepath=r"${escapedPath}", game_type='FO4')`,
        '        after = set(o.name for o in bpy.data.objects)',
        '        new_objs = [bpy.data.objects[n] for n in (after - before)]',
        "        armature_obj = next((o for o in new_objs if o.type == 'ARMATURE'), None)",
        '        if armature_obj is None:',
        '            result["error"] = "No armature (skeleton) found in this NIF."',
        '        else:',
        '            bones = []',
        '            for b in armature_obj.data.bones:',
        '                parent_head = b.parent.head_local if b.parent else b.head_local',
        '                bones.append({',
        '                    "id": b.name, "name": b.name,',
        '                    "parentId": b.parent.name if b.parent else None,',
        '                    "children": [c.name for c in b.children],',
        '                    "position": [b.head_local.x - parent_head.x, b.head_local.z - parent_head.z, b.head_local.y - parent_head.y],',
        '                    "rotation": [math.degrees(a) for a in b.matrix_local.to_euler()],',
        '                    "length": b.length,',
        '                })',
        '            result["success"] = True',
        '            result["bones"] = bones',
        '            result["armatureName"] = armature_obj.name',
        'except Exception as e:',
        '    result["error"] = str(e)',
        'print(json.dumps(result))',
      ].join('\n');

      const s = loadSettings();
      const payload: any = { type: 'script', code };
      if (s?.blenderLinkToken) payload.token = s.blenderLinkToken;
      const resp = await _sendToBlenderTCP(payload);
      if (!resp?.success) return { success: false, error: resp?.message || 'Blender Link is not connected. Open Blender with the Mossy Link v6 add-on running.' };

      const raw = String(resp?.result ?? '');
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      if (!jsonMatch) return { success: false, error: `Unexpected response from Blender: ${raw.slice(0, 200)}` };
      const parsed = JSON.parse(jsonMatch[0]);
      return parsed;
    } catch (error: any) {
      return { success: false, error: error?.message || String(error) };
    }
  });

  registerHandler('animation-editor:save-nif', async (_event, params: { nifPath: string; armatureName: string; bones: Array<{ name: string; position: [number, number, number] }> }) => {
    try {
      const { nifPath, armatureName, bones } = params;
      if (!nifPath) return { success: false, error: 'No output path provided.' };
      if (!armatureName || !Array.isArray(bones) || bones.length === 0) {
        return { success: false, error: 'No skeleton loaded to save — load a NIF first.' };
      }
      const escapedPath = nifPath.replace(/\\/g, '\\\\');
      const bonesJson = JSON.stringify(bones).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
      const code = [
        'import json',
        'result = {"success": False, "error": None}',
        'try:',
        `    armature_obj = bpy.data.objects.get("${armatureName.replace(/"/g, '')}")`,
        '    if armature_obj is None:',
        '        result["error"] = "Armature not found in the current Blender scene — reload the NIF before saving."',
        '    else:',
        `        edits = json.loads("${bonesJson}")`,
        '        edit_by_name = {e["name"]: e for e in edits}',
        '        bpy.context.view_layer.objects.active = armature_obj',
        "        bpy.ops.object.mode_set(mode='EDIT')",
        '        for eb in armature_obj.data.edit_bones:',
        '            e = edit_by_name.get(eb.name)',
        '            if not e:',
        '                continue',
        '            parent_head = eb.parent.head if eb.parent else eb.head',
        '            # e["position"] is [uiX, uiY, uiZ] in the editor\'s Y-up space (see load-nif);',
        '            # Blender is Z-up, so uiY (up) maps to Blender Z and uiZ (depth) maps to Blender Y.',
        '            ui_x, ui_y, ui_z = e["position"]',
        '            new_head = (parent_head.x + ui_x, parent_head.y + ui_z, parent_head.z + ui_y)',
        '            delta = (new_head[0] - eb.head.x, new_head[1] - eb.head.y, new_head[2] - eb.head.z)',
        '            eb.head = new_head',
        '            eb.tail = (eb.tail.x + delta[0], eb.tail.y + delta[1], eb.tail.z + delta[2])',
        "        bpy.ops.object.mode_set(mode='OBJECT')",
        `        bpy.ops.export_scene.pynifly(filepath=r"${escapedPath}", game_type='FO4')`,
        '        result["success"] = True',
        'except Exception as e:',
        '    result["error"] = str(e)',
        '    try:',
        "        bpy.ops.object.mode_set(mode='OBJECT')",
        '    except Exception:',
        '        pass',
        'print(json.dumps(result))',
      ].join('\n');

      const s = loadSettings();
      const payload: any = { type: 'script', code };
      if (s?.blenderLinkToken) payload.token = s.blenderLinkToken;
      const resp = await _sendToBlenderTCP(payload);
      if (!resp?.success) return { success: false, error: resp?.message || 'Blender Link is not connected.' };

      const raw = String(resp?.result ?? '');
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      if (!jsonMatch) return { success: false, error: `Unexpected response from Blender: ${raw.slice(0, 200)}` };
      return JSON.parse(jsonMatch[0]);
    } catch (error: any) {
      return { success: false, error: error?.message || String(error) };
    }
  });

