  // --- Install Script: xEdit .pas or Papyrus .psc ---
  registerHandler(IPC_CHANNELS.INSTALL_SCRIPT, async (_event, type: string, name: string, content: string) => {
    const startTime = Date.now();
    try {
      const settings = loadSettings() || {};
      let targetDir = '';
      let toolName = '';
      
      if (type === 'xedit') {
        toolName = 'xEdit';
        if (!settings?.xeditPath) {
          const error = new Error('xEdit path not configured in settings');
          auditLogger.log({
            operation: 'script-installation',
            tool: 'xedit',
            action: 'install-script',
            status: 'error',
            duration: Date.now() - startTime,
            error: error.message,
            details: { scriptName: name, scriptType: type }
          });
          throw error;
        }
        const xeditDir = path.dirname(settings.xeditPath);
        const scriptsDir = path.join(xeditDir, 'Edit Scripts');
        
        // Ensure directory exists
        if (!fs.existsSync(scriptsDir)) {
          fs.mkdirSync(scriptsDir, { recursive: true });
        }
        
        targetDir = path.join(scriptsDir, `${name}.pas`);
        fs.writeFileSync(targetDir, content, 'utf-8');
        console.log(`[install-script] ${toolName} script installed:`, targetDir);
        
        auditLogger.log({
          operation: 'script-installation',
          tool: 'xedit',
          action: 'install-script',
          status: 'success',
          duration: Date.now() - startTime,
          result: { path: targetDir, size: content.length },
          details: { scriptName: name, scriptType: type }
        });
        
      } else if (type === 'papyrus') {
        toolName = 'Papyrus (CK)';
        if (!settings?.creationKitPath) {
          const error = new Error('Creation Kit path not configured in settings');
          auditLogger.log({
            operation: 'script-installation',
            tool: 'ck',
            action: 'install-script',
            status: 'error',
            duration: Date.now() - startTime,
            error: error.message,
            details: { scriptName: name, scriptType: type }
          });
          throw error;
        }
        const ckDir = path.dirname(settings.creationKitPath);
        const scriptsDir = path.join(ckDir, 'Data', 'Scripts', 'Source');
        
        // Ensure directory exists
        if (!fs.existsSync(scriptsDir)) {
          fs.mkdirSync(scriptsDir, { recursive: true });
        }
        
        targetDir = path.join(scriptsDir, `${name}.psc`);
        fs.writeFileSync(targetDir, content, 'utf-8');
        console.log(`[install-script] ${toolName} script installed:`, targetDir);
        
        auditLogger.log({
          operation: 'script-installation',
          tool: 'ck',
          action: 'install-script',
          status: 'success',
          duration: Date.now() - startTime,
          result: { path: targetDir, size: content.length },
          details: { scriptName: name, scriptType: type }
        });
        
      } else {
        throw new Error(`Unknown script type: ${type}`);
      }
      
      return { success: true, path: targetDir };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[install-script] Error:', errMsg);
      
      // Only log if not already logged above
      if (error.message && !error.message.includes('configured in settings')) {
        auditLogger.log({
          operation: 'script-installation',
          tool: type || 'unknown',
          action: 'install-script',
          status: 'error',
          duration: Date.now() - startTime,
          error: errMsg,
          details: { scriptName: name, scriptType: type }
        });
      }
      
      return { success: false, error: errMsg };
    }
  });

  // --- FS: Stat path (exists/isFile/isDirectory) ---
  registerHandler('fs-stat', async (_event, targetPath: string) => {
    try {
      if (!targetPath || typeof targetPath !== 'string') {
        return { exists: false, isFile: false, isDirectory: false };
      }

      const p = targetPath.trim();
      if (!p) return { exists: false, isFile: false, isDirectory: false };
      if (!fs.existsSync(p)) return { exists: false, isFile: false, isDirectory: false };

      const st = fs.statSync(p);
      return { exists: true, isFile: st.isFile(), isDirectory: st.isDirectory() };
    } catch {
      return { exists: false, isFile: false, isDirectory: false };
    }
  });

  // --- FS: Get directory stats (file count, total size, last-modified) ---
  // Used by BackupManager to populate snapshot metadata.
  registerHandler('get-directory-stats', async (_event, dirPath: string) => {
    try {
      if (!dirPath || !fs.existsSync(dirPath)) return { fileCount: 0, totalBytes: 0, lastModified: null };
      let fileCount = 0;
      let totalBytes = 0;
      let lastModified = 0;
      const walk = (dir: string, depth = 0) => {
        if (depth > 8) return; // cap traversal depth
        try {
          for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
            const full = path.join(dir, entry.name);
            if (entry.isDirectory()) {
              walk(full, depth + 1);
            } else if (entry.isFile()) {
              fileCount++;
              try {
                const st = fs.statSync(full);
                totalBytes += st.size;
                if (st.mtimeMs > lastModified) lastModified = st.mtimeMs;
              } catch { /* skip locked files */ }
            }
          }
        } catch { /* skip unreadable dirs */ }
      };
      walk(dirPath);
      return { fileCount, totalBytes, lastModified: lastModified > 0 ? new Date(lastModified).toISOString() : null };
    } catch (e: any) {
      return { fileCount: 0, totalBytes: 0, lastModified: null, error: e?.message };
    }
  });

