  // Helper functions for roadmap generation
  function extractTitle(prompt: string): string {
    const words = prompt.split(' ');
    return words.slice(0, Math.min(4, words.length)).join(' ').replace(/[^\w\s]/g, '');
  }

  const ROADMAP_TOOLS = ['blender', 'image-suite', 'ck', 'scribe', 'nifskope', 'general'] as const;

  /**
   * Generate a roadmap tailored to the user's actual prompt via the same
   * multi-tier LLM chain used by the Creative Director (Inkling → Ollama →
   * Groq → local KoboldCpp — see cdCallAgent()). Only falls back to the
   * static template below if every provider is unreachable, and reports
   * that honestly via `aiGenerated: false` rather than pretending.
   */
  async function generateRoadmapStepsWithAI(prompt: string): Promise<{ steps: any[]; aiGenerated: boolean }> {
    try {
      const systemPrompt = [
        'You are Mossy, an expert Fallout 4 modding project planner inside MOSSY.SPACE.',
        'Given the user\'s mod idea, produce 4 to 8 concrete build steps tailored specifically',
        'to what they described — not a generic template. Reference real Fallout 4 modding',
        'workflows where relevant (Creation Kit records, Papyrus scripting, xEdit conflict',
        'resolution, NIF/material work, BA2 packaging, load-order/SEQ considerations, etc.).',
        'Order steps logically from planning to release.',
        `Respond with ONLY a JSON array, no prose, no markdown fences. Each element must be an`,
        `object: {"title": string, "description": string (1-2 sentences), "tool": one of ${JSON.stringify(ROADMAP_TOOLS)} }.`,
        'Pick whichever tool is most relevant to that step, or "general" if none fit.'
      ].join(' ');

      const raw = await cdCallAgent(systemPrompt, prompt, 2048);
      const jsonMatch = raw.match(/\[[\s\S]*\]/);
      if (!jsonMatch) throw new Error('AI response did not contain a JSON array');
      const parsed = JSON.parse(jsonMatch[0]);
      if (!Array.isArray(parsed) || parsed.length === 0) throw new Error('AI response was not a non-empty array');

      const steps = parsed.slice(0, 12).map((s: any, i: number) => {
        const step: any = {
          id: `step-${i + 1}-${Date.now()}`,
          title: String(s?.title || `Step ${i + 1}`).slice(0, 120),
          description: String(s?.description || '').slice(0, 500),
          status: 'not-started',
          order: i + 1,
        };
        if (typeof s?.tool === 'string' && (ROADMAP_TOOLS as readonly string[]).includes(s.tool) && s.tool !== 'general') {
          step.tool = s.tool;
        }
        return step;
      });

      return { steps, aiGenerated: true };
    } catch (err) {
      console.warn('[Roadmap] AI generation unavailable, falling back to template steps:', err);
      return { steps: parseRoadmapStepsTemplate(prompt), aiGenerated: false };
    }
  }

  function parseRoadmapStepsTemplate(prompt: string): any[] {
    // Generate default steps based on the prompt
    const tools = ['blender', 'image-suite', 'ck', 'scribe', 'nifskope'];
    const tools_map: { [k: string]: string } = {
      'blender': 'blender',
      'image': 'image-suite',
      'texture': 'image-suite',
      'script': 'scribe',
      'nif': 'nifskope',
      'model': 'blender',
      '3d': 'blender',
    };

    const defaultSteps = [
      {
        id: `step-1-${Date.now()}`,
        title: 'Plan the project structure',
        description: 'Outline the scope, requirements, and resources needed for this mod.',
        status: 'not-started',
        order: 1,
      },
      {
        id: `step-2-${Date.now()}`,
        title: 'Gather assets and resources',
        description: 'Collect or create necessary 3D models, textures, scripts, and documentation.',
        status: 'not-started',
        order: 2,
        tool: 'blender',
      },
      {
        id: `step-3-${Date.now()}`,
        title: 'Create or import assets',
        description: 'Use appropriate tools to create or import your content into the engine.',
        status: 'not-started',
        order: 3,
        tool: detectToolFromPrompt(prompt),
      },
      {
        id: `step-4-${Date.now()}`,
        title: 'Script and automate',
        description: 'Write Papyrus scripts or implement game logic to bring your content to life.',
        status: 'not-started',
        order: 4,
        tool: 'scribe',
      },
      {
        id: `step-5-${Date.now()}`,
        title: 'Test and validate',
        description: 'Test your mod in-game, fix bugs, and validate all changes work as expected.',
        status: 'not-started',
        order: 5,
      },
      {
        id: `step-6-${Date.now()}`,
        title: 'Package and release',
        description: 'Create the final ESP/ESM, BA2 archives, and prepare for distribution.',
        status: 'not-started',
        order: 6,
      },
    ];

    return defaultSteps;
  }

  function detectToolFromPrompt(prompt: string): string {
    const promptLower = prompt.toLowerCase();
    const toolMap: { [k: string]: string } = {
      'blender': 'blender',
      'image': 'image-suite',
      'texture': 'image-suite',
      'script': 'scribe',
      'nif': 'nifskope',
      'model': 'blender',
      '3d': 'blender',
      'paint': 'image-suite',
      'weapon': 'blender',
      'armor': 'blender',
      'quest': 'scribe',
      'dialogue': 'scribe',
    };

    for (const [keyword, tool] of Object.entries(toolMap)) {
      if (promptLower.includes(keyword)) {
        return tool;
      }
    }

    return 'general';
  }



  // ============================================================================
  // WHAT'S NEW IPC HANDLERS (Platform 7)
  // ============================================================================

  // In-memory cache with persistent storage to disk
  const whatsNewStorage = new Map<string, any>();

  const compareSemverDesc = (a: string, b: string): number => {
    const aParts = a.split('.').map((part) => Number.parseInt(part, 10) || 0);
    const bParts = b.split('.').map((part) => Number.parseInt(part, 10) || 0);
    for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
      const diff = (bParts[i] || 0) - (aParts[i] || 0);
      if (diff !== 0) return diff;
    }
    return 0;
  };

  const findChangelogPath = (): string | null => {
    const candidates = [
      path.join(app.getAppPath(), 'CHANGELOG.md'),
      path.join(app.getAppPath(), '..', 'CHANGELOG.md'),
      path.join(app.getAppPath(), '..', '..', 'CHANGELOG.md'),
      path.join(process.resourcesPath, 'CHANGELOG.md'),
      path.join(process.cwd(), 'CHANGELOG.md'),
    ];
    return candidates.find((candidate) => fs.existsSync(candidate)) || null;
  };

  const toFeature = (rawLine: string) => {
    const cleaned = rawLine
      .replace(/^-\s+/, '')
      .replace(/\*\*/g, '')
      .trim();
    if (!cleaned) return null;
    const [left, ...rest] = cleaned.split(':');
    const description = rest.join(':').trim();
    return {
      title: description ? left.trim() : cleaned.slice(0, 72),
      description: description || cleaned,
      icon: '✨',
    };
  };

  const parseWhatsNewEntriesFromChangelog = (): any[] => {
    try {
      const changelogPath = findChangelogPath();
      if (!changelogPath) return [];
      const markdown = fs.readFileSync(changelogPath, 'utf-8');
      const versionMatches = Array.from(markdown.matchAll(/^##\s+\[(\d+\.\d+\.\d+)\][^\n]*$/gm));
      if (versionMatches.length === 0) return [];

      const parsedEntries: any[] = [];
      for (let index = 0; index < versionMatches.length; index++) {
        const version = versionMatches[index][1];
        const sectionStart = versionMatches[index].index ?? 0;
        const sectionEnd = versionMatches[index + 1]?.index ?? markdown.length;
        const section = markdown.slice(sectionStart, sectionEnd);
        const bulletLines = section
          .split('\n')
          .map((line) => line.trim())
          .filter((line) => line.startsWith('- '));

        // No artificial cap here — a real release's changelog can legitimately have more
        // than 24 bullets, and silently dropping the rest previously made new entries
        // invisible in What's New without any indication anything was cut.
        const features = bulletLines
          .map(toFeature)
          .filter(Boolean);

        parsedEntries.push({
          id: `whats-new-${version}`,
          version,
          releaseDate: Date.now() - (index * 24 * 60 * 60 * 1000),
          title: `What's New in Mossy v${version}`,
          features,
          highlights: bulletLines.slice(0, 12).map((line) => line.replace(/^-\s+/, '').trim()),
          createdAt: Date.now(),
          updatedAt: Date.now(),
        });
      }

      return parsedEntries;
    } catch (error) {
      console.warn('[WhatsNew] Failed to parse CHANGELOG.md:', error);
      return [];
    }
  };

  // Load What's New entries from persistent storage
  const loadWhatsNewFromDisk = (): Map<string, any> => {
    try {
      const settings = loadSettings();
      const savedEntries = settings?.whatsNewEntries || [];
      const map = new Map<string, any>();
      for (const entry of savedEntries) {
        map.set(entry.id, entry);
      }
      console.log(`[WhatsNew] Loaded ${map.size} entries from persistent storage`);
      return map;
    } catch (err) {
      console.warn('[WhatsNew] Failed to load entries from disk:', err);
      return new Map<string, any>();
    }
  };

  // Save all What's New entries to persistent storage
  const saveWhatsNewToDisk = (map: Map<string, any>): boolean => {
    try {
      const entriesArray = Array.from(map.values());
      const currentSettings = loadSettings();
      currentSettings.whatsNewEntries = entriesArray;
      saveSettings(currentSettings);
      console.log(`[WhatsNew] Saved ${entriesArray.length} entries to persistent storage`);
      return true;
    } catch (err) {
      console.error('[WhatsNew] Failed to save entries to disk:', err);
      return false;
    }
  };

  // Initialize storage from disk
  whatsNewStorage.clear();
  const initialWhatsNewEntries = loadWhatsNewFromDisk();
  for (const [id, entry] of initialWhatsNewEntries) {
    whatsNewStorage.set(id, entry);
  }
  const changelogEntries = parseWhatsNewEntriesFromChangelog();
  for (const entry of changelogEntries) {
    whatsNewStorage.set(entry.id, entry);
  }
  if (changelogEntries.length > 0) {
    saveWhatsNewToDisk(whatsNewStorage);
  }

  // Get all What's New entries
  registerHandler('whats-new-get-all', async (_event) => {
    const startTime = Date.now();
    try {
      const entries = Array.from(whatsNewStorage.values());

      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-all',
        status: 'success',
        duration: Date.now() - startTime,
        result: { entryCount: entries.length }
      });

      return {
        ok: true,
        entries: entries,
        count: entries.length
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error getting all entries:', errMsg);
      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-all',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg
      });
      return {
        ok: false,
        error: errMsg,
        entries: []
      };
    }
  });

  // Get current version's What's New entry
  forceHandle('whats-new-get-current', async (_event) => {
    const startTime = Date.now();
    try {
      const currentVersion = require('../../package.json').version;
      const entryId = `whats-new-${currentVersion}`;
      const directEntry = whatsNewStorage.get(entryId);
      let entry = directEntry || null;
      let fallbackUsed = false;
      let fallbackVersion: string | null = null;
      if (!entry) {
        const candidates = Array.from(whatsNewStorage.values())
          .filter((item: any) => typeof item?.version === 'string');
        candidates.sort((a: any, b: any) => compareSemverDesc(a.version, b.version));
        entry = candidates[0] || null;
        fallbackUsed = !!entry;
        fallbackVersion = entry?.version || null;
      }

      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-current',
        status: 'success',
        duration: Date.now() - startTime,
        result: { found: !!entry, version: currentVersion, fallbackUsed, fallbackVersion }
      });

      return {
        ok: true,
        entry: entry || null,
        version: currentVersion,
        fallback: {
          used: fallbackUsed,
          requestedVersion: currentVersion,
          resolvedVersion: entry?.version || null,
        },
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error getting current entry:', errMsg);
      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-current',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg
      });
      return {
        ok: false,
        error: errMsg,
        entry: null
      };
    }
  });

  // Get full changelog (all entries as markdown)
  registerHandler('whats-new-get-changelog', async (_event) => {
    const startTime = Date.now();
    try {
      const entries = Array.from(whatsNewStorage.values())
        .sort((a: any, b: any) => b.releaseDate - a.releaseDate);

      let markdown = '# Mossy Changelog\n\n';
      for (const entry of entries) {
        markdown += `## ${entry.title} (${new Date(entry.releaseDate).toLocaleDateString()})\n\n`;
        
        if (entry.highlights && entry.highlights.length > 0) {
          markdown += '### Highlights\n';
          for (const h of entry.highlights) {
            markdown += `- ${h}\n`;
          }
          markdown += '\n';
        }

        if (entry.features && entry.features.length > 0) {
          markdown += '### Features\n';
          for (const f of entry.features) {
            markdown += `- **${f.title}**: ${f.description}\n`;
          }
          markdown += '\n';
        }

        if (entry.bugFixes && entry.bugFixes.length > 0) {
          markdown += '### Bug Fixes\n';
          for (const b of entry.bugFixes) {
            markdown += `- ${b}\n`;
          }
          markdown += '\n';
        }

        if (entry.breakingChanges && entry.breakingChanges.length > 0) {
          markdown += '### ⚠️ Breaking Changes\n';
          for (const bc of entry.breakingChanges) {
            markdown += `- ${bc}\n`;
          }
          markdown += '\n';
        }
      }

      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-changelog',
        status: 'success',
        duration: Date.now() - startTime,
        result: { entryCount: entries.length, markdownLength: markdown.length }
      });

      return {
        ok: true,
        changelog: markdown,
        entryCount: entries.length
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error generating changelog:', errMsg);
      auditLogger.log({
        operation: 'whats-new-retrieval',
        tool: 'whats-new',
        action: 'get-changelog',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg
      });
      return {
        ok: false,
        error: errMsg,
        changelog: ''
      };
    }
  });

  // Mark a version as seen
  registerHandler('whats-new-mark-seen', async (_event, params: { version: string }) => {
    const startTime = Date.now();
    try {
      const { version } = params;

      // Validate version
      const versionValidation = IpcValidation.isNonEmptyString(version, 'version');
      if (!versionValidation.valid) {
        auditLogger.log({
          operation: 'whats-new-update',
          tool: 'whats-new',
          action: 'mark-seen',
          status: 'error',
          duration: Date.now() - startTime,
          error: versionValidation.error
        });
        return {
          ok: false,
          error: versionValidation.error
        };
      }

      const currentSettings = loadSettings();
      if (!currentSettings.whatsNewSeenVersions) {
        currentSettings.whatsNewSeenVersions = [];
      }
      
      if (!currentSettings.whatsNewSeenVersions.includes(version)) {
        currentSettings.whatsNewSeenVersions.push(version);
        saveSettings(currentSettings);
      }

      auditLogger.log({
        operation: 'whats-new-update',
        tool: 'whats-new',
        action: 'mark-seen',
        status: 'success',
        duration: Date.now() - startTime,
        result: { version, seenCount: currentSettings.whatsNewSeenVersions.length }
      });

      return {
        ok: true,
        message: `Version ${version} marked as seen`
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error marking as seen:', errMsg);
      auditLogger.log({
        operation: 'whats-new-update',
        tool: 'whats-new',
        action: 'mark-seen',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg,
        details: { version: (params?.version || '').substring(0, 20) }
      });
      return {
        ok: false,
        error: errMsg
      };
    }
  });

  // Dismiss a version permanently
  registerHandler('whats-new-dismiss', async (_event, params: { version: string }) => {
    const startTime = Date.now();
    try {
      const { version } = params;

      // Validate version
      const versionValidation = IpcValidation.isNonEmptyString(version, 'version');
      if (!versionValidation.valid) {
        auditLogger.log({
          operation: 'whats-new-update',
          tool: 'whats-new',
          action: 'dismiss',
          status: 'error',
          duration: Date.now() - startTime,
          error: versionValidation.error
        });
        return {
          ok: false,
          error: versionValidation.error
        };
      }

      const currentSettings = loadSettings();
      if (!currentSettings.whatsNewDismissedVersions) {
        currentSettings.whatsNewDismissedVersions = [];
      }

      if (!currentSettings.whatsNewDismissedVersions.includes(version)) {
        currentSettings.whatsNewDismissedVersions.push(version);
        saveSettings(currentSettings);
      }

      auditLogger.log({
        operation: 'whats-new-update',
        tool: 'whats-new',
        action: 'dismiss',
        status: 'success',
        duration: Date.now() - startTime,
        result: { version, dismissedCount: currentSettings.whatsNewDismissedVersions.length }
      });

      return {
        ok: true,
        message: `Version ${version} dismissed`
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error dismissing:', errMsg);
      auditLogger.log({
        operation: 'whats-new-update',
        tool: 'whats-new',
        action: 'dismiss',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg,
        details: { version: (params?.version || '').substring(0, 20) }
      });
      return {
        ok: false,
        error: errMsg
      };
    }
  });

  // Reset dismissals (useful for testing)
  registerHandler('whats-new-reset', async (_event) => {
    const startTime = Date.now();
    try {
      const currentSettings = loadSettings();
      currentSettings.whatsNewDismissedVersions = [];
      currentSettings.whatsNewSeenVersions = [];
      saveSettings(currentSettings);

      auditLogger.log({
        operation: 'whats-new-reset',
        tool: 'whats-new',
        action: 'reset-dismissals',
        status: 'success',
        duration: Date.now() - startTime,
        result: { dismissed: 'all cleared', seen: 'all cleared' }
      });

      return {
        ok: true,
        message: 'All dismissals reset'
      };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[WhatsNew] Error resetting:', errMsg);
      auditLogger.log({
        operation: 'whats-new-reset',
        tool: 'whats-new',
        action: 'reset-dismissals',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg
      });
      return {
        ok: false,
        error: errMsg
      };
    }
  });


  // ============================================================================
