  registerHandler('analytics:get-metrics-summary', async () => {
    const startTime = Date.now();
    try {
      const events = Array.from(analyticsStorage.values());
      // averageBuildTime and topFeatures used to be hardcoded (2500ms, three fixed
      // feature names) regardless of what actually happened — now computed from
      // real tracked events, honestly null/empty when there's nothing to compute from.
      const buildEventsWithDuration = events.filter((e: any) => e.event === 'build' && typeof e.properties?.durationMs === 'number');
      const averageBuildTime = buildEventsWithDuration.length > 0
        ? Math.round(buildEventsWithDuration.reduce((sum: number, e: any) => sum + e.properties.durationMs, 0) / buildEventsWithDuration.length)
        : null;
      const categoryCounts = new Map<string, number>();
      for (const e of events) {
        const cat = e.category || e.event || 'uncategorized';
        categoryCounts.set(cat, (categoryCounts.get(cat) || 0) + 1);
      }
      const topFeatures = Array.from(categoryCounts.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([feature, usage]) => ({ feature, usage }));
      const summary = {
        totalEvents: events.length,
        buildCount: events.filter((e: any) => e.event === 'build').length,
        successRate: events.length > 0 ? (events.filter((e: any) => e.success).length / events.length * 100).toFixed(1) : 100,
        averageBuildTime,
        assetsCreated: events.filter((e: any) => e.event.includes('asset')).length,
        errorsEncountered: events.filter((e: any) => !e.success).length,
        timeSpent: Math.floor((Date.now() - (events[0]?.timestamp || Date.now())) / 1000 / 60),
        topFeatures
      };
      auditLogger.log({
        operation: 'metrics-retrieval',
        tool: 'analytics-reporting',
        action: 'get-metrics-summary',
        status: 'success',
        duration: Date.now() - startTime,
        result: { totalEvents: summary.totalEvents }
      });
      return { success: true, summary };
    } catch (error: any) {
      const errMsg = error instanceof Error ? error.message : String(error);
      console.error('[Main] analytics:get-metrics-summary error:', errMsg);
      auditLogger.log({
        operation: 'metrics-retrieval',
        tool: 'analytics-reporting',
        action: 'get-metrics-summary',
        status: 'error',
        duration: Date.now() - startTime,
        error: errMsg
      });
      return { success: false, error: errMsg };
    }
  });


