  // Material Manifest Handlers
  registerHandler('material:load-manifest', async (_event, filePath: string) => {
    try {
      const validation = IpcValidation.isValidFilePath(filePath);
      if (!validation.valid) return IpcResponseBuilder.error(validation.error ?? "Validation error", IpcErrorCode.EINVAL);
      if (!fs.existsSync(filePath)) {
        return IpcResponseBuilder.error('Manifest file not found', IpcErrorCode.ENOENT);
      }

      const content = fs.readFileSync(filePath, 'utf-8');
      let manifest;
      try {
        manifest = JSON.parse(content);
      } catch (parseErr) {
        return IpcResponseBuilder.error('Invalid JSON in manifest file', IpcErrorCode.INVALID_ASSET);
      }

      // Validate manifest structure
      if (!manifest.modName || typeof manifest.modName !== 'string') {
        return IpcResponseBuilder.error('Missing or invalid modName field', IpcErrorCode.INVALID_ASSET);
      }
      if (!Array.isArray(manifest.materials)) {
        return IpcResponseBuilder.error('Missing or invalid materials array', IpcErrorCode.INVALID_ASSET);
      }

      // Deep validation of material entries
      for (let i = 0; i < manifest.materials.length; i++) {
        const mat = manifest.materials[i];
        if (!mat.name || typeof mat.name !== 'string') {
          return IpcResponseBuilder.error(`Material ${i}: Missing or invalid name`, IpcErrorCode.INVALID_ASSET);
        }
      }

      const stat = fs.statSync(filePath);
      console.log(`[Material Manifest] Loaded: ${manifest.modName}, ${manifest.materials.length} materials, ${stat.size} bytes`);

      return IpcResponseBuilder.success({
        manifest,
        metadata: {
          filePath,
          fileSize: stat.size,
          modName: manifest.modName,
          materialCount: manifest.materials.length,
          lastModified: stat.mtime.getTime(),
        },
      });
    } catch (error) {
      console.error('[Material Load Manifest] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  registerHandler('material:save-manifest', async (_event, params: any) => {
    try {
      const { filePath, manifest } = params;
      const validation = IpcValidation.isValidFilePath(filePath);
      if (!validation.valid) return IpcResponseBuilder.error(validation.error ?? "Validation error", IpcErrorCode.EINVAL);
      
      // Validate manifest structure
      if (!manifest.modName || typeof manifest.modName !== 'string') {
        return IpcResponseBuilder.error('Invalid manifest: missing modName', IpcErrorCode.INVALID_ASSET);
      }
      if (!Array.isArray(manifest.materials)) {
        return IpcResponseBuilder.error('Invalid manifest: materials must be array', IpcErrorCode.INVALID_ASSET);
      }

      // Deep validation
      for (let i = 0; i < manifest.materials.length; i++) {
        const mat = manifest.materials[i];
        if (!mat.name || typeof mat.name !== 'string') {
          return IpcResponseBuilder.error(`Material ${i}: missing name`, IpcErrorCode.INVALID_ASSET);
        }
      }

      const dir = path.dirname(filePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      // Create backup if file exists
      if (fs.existsSync(filePath)) {
        const backupPath = filePath + '.backup-' + Date.now();
        fs.copyFileSync(filePath, backupPath);
      }

      // Write with pretty formatting
      fs.writeFileSync(filePath, JSON.stringify(manifest, null, 2), 'utf-8');
      const stat = fs.statSync(filePath);

      console.log(`[Material Save Manifest] Saved: ${manifest.modName}, ${manifest.materials.length} materials, ${stat.size} bytes`);
      return IpcResponseBuilder.success({
        filePath,
        saved: true,
        fileSize: stat.size,
        materialCount: manifest.materials.length,
        timestamp: Date.now(),
      });
    } catch (error) {
      console.error('[Material Save Manifest] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  /**
   * Material Editor "Bake Textures". The node graph in MaterialEditor.tsx is
   * a layout/planning tool — its nodes carry no evaluatable color/texture
   * data, so there is nothing to render a real shader graph from. What IS
   * real is the material's Base Color / Metallic / Roughness values the user
   * actually set, and (when supplied) a real source texture. So this bakes:
   *  - with a `baseTexturePath`: a genuine PBR set (diffuse/normal/roughness/
   *    metallic/ao) via the existing TextureGeneratorEngine (sharp-based,
   *    previously implemented but never wired to any UI), using the real
   *    slider values for roughness/metallic instead of its defaults.
   *  - without one: real solid-color PNGs baked directly from the material's
   *    actual Base Color / Metallic / Roughness values via sharp.
   */
  registerHandler('material:bake-textures', async (_event, params: {
    materialName: string; outputDir: string; baseTexturePath?: string;
    baseColorHex: string; metallic: number; roughness: number; resolution?: number;
  }) => {
    try {
      const { materialName, outputDir, baseTexturePath, baseColorHex, metallic, roughness } = params;
      const resolution = params.resolution || 1024;
      if (!outputDir) return { success: false, error: 'No output directory selected.' };
      if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir, { recursive: true });
      const safeName = (materialName || 'material').replace(/[^\w\-]/g, '_');

      if (baseTexturePath && fs.existsSync(baseTexturePath)) {
        const engine = new TextureGeneratorEngine();
        await engine.initialize();
        const maps: Array<{ type: string; path: string; width: number; height: number }> = [];
        const specs: Array<{ type: 'diffuse' | 'normal' | 'roughness' | 'metallic' | 'ao'; settings: any }> = [
          { type: 'diffuse', settings: { resolution } },
          { type: 'normal', settings: { resolution, normalStrength: 2.0 } },
          { type: 'roughness', settings: { resolution, roughnessMin: Math.max(0, roughness - 0.15), roughnessMax: Math.min(1, roughness + 0.15) } },
          { type: 'metallic', settings: { resolution, metallicValue: metallic } },
          { type: 'ao', settings: { resolution, aoIntensity: 0.5 } },
        ];
        for (const spec of specs) {
          const result = await engine.generateMap(spec.type, baseTexturePath, { ...spec.settings, resolution });
          if (result.success) maps.push({ type: spec.type, path: result.outputPath, width: result.width, height: result.height });
        }
        return { success: maps.length > 0, outputDir, maps, mode: 'pbr-from-source' };
      }

      // No source texture: bake real solid-color maps from the material's actual property values.
      const hex = (baseColorHex || '#FFFFFF').replace('#', '');
      const r = parseInt(hex.slice(0, 2), 16) || 255;
      const g = parseInt(hex.slice(2, 4), 16) || 255;
      const b = parseInt(hex.slice(4, 6), 16) || 255;
      const metallicGray = Math.round((metallic ?? 0.5) * 255);
      const roughnessGray = Math.round((roughness ?? 0.5) * 255);

      const outputs: Array<{ type: string; file: string; color: { r: number; g: number; b: number } }> = [
        { type: 'diffuse', file: `${safeName}_diffuse.png`, color: { r, g, b } },
        { type: 'metallic', file: `${safeName}_metallic.png`, color: { r: metallicGray, g: metallicGray, b: metallicGray } },
        { type: 'roughness', file: `${safeName}_roughness.png`, color: { r: roughnessGray, g: roughnessGray, b: roughnessGray } },
      ];

      const maps: Array<{ type: string; path: string; width: number; height: number }> = [];
      for (const out of outputs) {
        const outPath = path.join(outputDir, out.file);
        await sharp({ create: { width: resolution, height: resolution, channels: 4, background: { ...out.color, alpha: 1 } } })
          .png()
          .toFile(outPath);
        maps.push({ type: out.type, path: outPath, width: resolution, height: resolution });
      }

      return { success: true, outputDir, maps, mode: 'flat-from-properties' };
    } catch (error: any) {
      console.error('[Material Bake Textures] Error:', error);
      return { success: false, error: error?.message || String(error) };
    }
  });

  /**
   * Writes a REAL binary .bgsm file (see src/electron/bgsmWriter.ts) rather
   * than the JSON-with-a-.bgsm-extension BGSMEditor.tsx used to export —
   * that file would never load in the Creation Kit or the game itself since
   * it isn't actually the Bethesda binary format. Only BGSM version 2
   * (Fallout 4) is supported; FO76's v20+ format is intentionally rejected
   * rather than guessed at.
   */
  registerHandler('material:write-bgsm-binary', async (_event, params: { data: BgsmWriteInput & { version?: number }; defaultFileName: string }) => {
    try {
      const { data, defaultFileName } = params;
      if (data?.version !== undefined && data.version !== 2) {
        return { success: false, error: `Binary .bgsm export only supports version 2 (Fallout 4) right now — version ${data.version} (FO76) is not yet implemented.` };
      }
      const result = await dialog.showSaveDialog({
        defaultPath: defaultFileName || 'material.bgsm',
        filters: [{ name: 'Fallout 4 Material', extensions: ['bgsm'] }],
      });
      if (result.canceled || !result.filePath) return { success: false, error: 'Save cancelled.' };

      writeBgsmFile(data, result.filePath);
      const stat = fs.statSync(result.filePath);
      return { success: true, filePath: result.filePath, fileSize: stat.size };
    } catch (error: any) {
      console.error('[BGSM Writer] Error:', error);
      return { success: false, error: error?.message || String(error) };
    }
  });

  /**
   * TextureEnhancer.tsx: native single-file picker for the source texture
   * (Single Texture mode). Broader extension set than pickDdsFile since this
   * tool accepts PNG/TGA/JPG source photos, not just game-ready DDS.
   */
  registerHandler('texture-enhancer:pick-input-texture', async () => {
    const result = await dialog.showOpenDialog({
      title: 'Select Source Texture',
      properties: ['openFile'],
      filters: [
        { name: 'Textures', extensions: ['dds', 'png', 'tga', 'jpg', 'jpeg', 'bmp', 'tiff'] },
        { name: 'All Files', extensions: ['*'] },
      ],
    });
    if (result.canceled || !result.filePaths?.length) return null;
    return result.filePaths[0];
  });

  /**
   * TextureEnhancer.tsx backend — real PBR map extraction from a source
   * texture via the sharp-based TextureGeneratorEngine (previously fully
   * implemented in src/mining/textureGenerator.ts but never wired to any
   * IPC channel, so this UI's "real" branch always hit an unregistered
   * channel and silently fell through to a fake simulated-progress demo).
   * Cavity extraction and true binary .bgsm writing are not implemented —
   * reported honestly via `errors`/`note` rather than faked.
   */
  const TEXTURE_ENHANCER_EXTENSIONS = ['.dds', '.png', '.tga', '.jpg', '.jpeg', '.bmp', '.tiff'];

  // Material-aware positive prompts for the AI Detail Synthesis stage — built
  // to match the Texture Enhancer's own MaterialSurface options, so the
  // generated detail actually fits the surface type the user already selected
  // rather than a generic "make it detailed" prompt.
  const MATERIAL_DETAIL_PROMPTS: Record<string, string> = {
    auto: 'highly detailed photorealistic material surface, fine micro-detail, sharp texture, 8k texture scan',
    metal_clean: 'clean brushed metal surface, fine machining marks, photorealistic metal texture, 8k texture scan',
    metal_weathered: 'weathered worn metal surface, fine scratches and wear patterns, photorealistic, 8k texture scan',
    metal_rusted: 'heavily oxidized rusted metal surface, fine pitting and corrosion detail, photorealistic, 8k texture scan',
    concrete: 'detailed concrete surface, fine aggregate and pore texture, weathered photorealistic concrete, 8k texture scan',
    stone: 'detailed rock surface, fine mineral grain and crack detail, weathered photorealistic stone, 8k texture scan',
    brick: 'detailed brick surface, fine mortar and weathering texture, photorealistic, 8k texture scan',
    wood_rough: 'rough weathered wood grain, fine splinter and cracking detail, photorealistic, 8k texture scan',
    wood_polished: 'polished wood grain, fine natural wood detail, photorealistic, 8k texture scan',
    fabric: 'detailed woven fabric texture, fine thread and weave detail, photorealistic, 8k texture scan',
    organic: 'intricate organic surface detail, fine veining and biological texture, dense micro-detail, photorealistic, 8k texture scan',
    painted: 'detailed painted surface, fine brush texture and micro-cracking, photorealistic, 8k texture scan',
    plastic: 'detailed plastic surface, fine molding and wear texture, photorealistic, 8k texture scan',
    leather: 'detailed leather surface, fine grain and creasing texture, photorealistic, 8k texture scan',
  };
  const AI_DETAIL_NEGATIVE_PROMPT = 'blurry, flat, low detail, smooth, plain, cartoon, illustration, painting, low resolution, watermark, text';

  const enhanceOneTexture = async (inputPath: string, outputFolder: string | undefined, params: {
    quality: string; outputFormat: string; pipeline: any; surface?: string;
  }): Promise<{ success: boolean; outputs: Record<string, string>; errors: string[]; note?: string; error?: string }> => {
    try {
      const { pipeline } = params;
      if (!inputPath || !fs.existsSync(inputPath)) {
        return { success: false, outputs: {}, errors: [], error: 'Input texture not found on disk. Use the native file picker (not drag-and-drop in a browser preview) so a real file path is available.' };
      }
      const outDir = outputFolder && fs.existsSync(outputFolder) ? outputFolder : path.dirname(inputPath);
      const baseName = path.basename(inputPath, path.extname(inputPath));
      const resolution = params.quality === 'maximum' ? 4096 : params.quality === 'fast' ? 1024 : 2048;

      const outputs: Record<string, string> = {};
      const errors: string[] = [];

      // AI Detail Synthesis — runs BEFORE the classical pipeline below. Unlike
      // every other stage here (deterministic Sharp/edge-detection processing
      // that can only enhance detail already present in the source pixels),
      // this generates genuinely new fine surface detail via the user's own
      // ComfyUI install, then everything downstream (normal/roughness/AO/etc.)
      // derives from that enriched result instead of the flatter original.
      let workingInputPath = inputPath;
      if (pipeline?.aiDetail?.enabled) {
        if (!pipeline.aiDetail.model) {
          errors.push('AI detail synthesis: no ComfyUI checkpoint selected — skipped, continuing with original texture.');
        } else {
          try {
            const uploadResult = await comfyuiUploadImage(inputPath);
            if (!uploadResult.success || !uploadResult.name) {
              errors.push(`AI detail synthesis: ${uploadResult.error || 'upload to ComfyUI failed'} — continuing with original texture.`);
            } else {
              const surfaceKey = params.surface || 'auto';
              const positivePrompt = String(pipeline.aiDetail.promptOverride || '').trim()
                || MATERIAL_DETAIL_PROMPTS[surfaceKey] || MATERIAL_DETAIL_PROMPTS.auto;
              const workflow = buildComfyImg2ImgWorkflow({
                model: pipeline.aiDetail.model,
                positive: positivePrompt,
                negative: AI_DETAIL_NEGATIVE_PROMPT,
                steps: Math.round(pipeline.aiDetail.steps ?? 30),
                cfg: pipeline.aiDetail.cfg ?? 6,
                seed: Math.floor(Math.random() * 1_000_000),
                denoise: pipeline.aiDetail.denoise ?? 0.45,
                uploadedImage: uploadResult.name,
              });
              const runResult = await comfyuiRunWorkflow(workflow);
              if (runResult.success && runResult.imageData) {
                workingInputPath = saveComfyuiResult(inputPath, 'ai_detailed', runResult.imageData);
                outputs.aiDetailSource = workingInputPath;
              } else {
                errors.push(`AI detail synthesis: ${runResult.error || 'generation failed'} — continuing with original texture.`);
              }
            }
          } catch (err: any) {
            errors.push(`AI detail synthesis: ${err?.message || err} — continuing with original texture.`);
          }
        }
      }

      const engine = new TextureGeneratorEngine();
      await engine.initialize();

      const tryGenerate = async (key: string, type: TextureMapType, settings: any) => {
        try {
          const result = await engine.generateMap(type, workingInputPath, { resolution, ...settings });
          if (result.success) outputs[key] = result.outputPath;
          else errors.push(`${key}: ${result.error || 'generation failed'}`);
        } catch (err: any) {
          errors.push(`${key}: ${err?.message || err}`);
        }
      };

      if (pipeline?.albedo?.enabled) {
        if (pipeline.albedo.seamless) {
          const seamless = await engine.makeSeamless(workingInputPath, Math.round((pipeline.albedo.seamlessBlend ?? 0.5) * 128));
          if (seamless.success) outputs.albedo = seamless.outputPath;
          else errors.push(`albedo: ${seamless.error || 'seamless blend failed'}`);
        } else {
          await tryGenerate('albedo', 'diffuse', {});
        }
      }
      if (pipeline?.normal?.enabled) {
        await tryGenerate('normal', 'normal', {
          normalStrength: pipeline.normal.strength,
          normalMethod: pipeline.normal.method,
          normalSmoothing: pipeline.normal.smoothing,
          normalFineDetail: pipeline.normal.fineDetail,
          invertY: pipeline.normal.invertY,
        });
      }
      if (pipeline?.roughness?.enabled) {
        const base = pipeline.roughness.base ?? 0.5;
        const variation = pipeline.roughness.variation ?? 0.1;
        await tryGenerate('roughness', 'roughness', {
          roughnessMin: Math.max(0, base - variation),
          roughnessMax: Math.min(1, base + variation),
        });
      }
      if (pipeline?.metallic?.enabled) {
        const metallicValue = pipeline.metallic.mode === 'zero' ? 0 : (pipeline.metallic.base ?? 0);
        await tryGenerate('metallic', 'metallic', { metallicValue });
      }
      if (pipeline?.specular?.enabled) {
        await tryGenerate('specular', 'specular', {
          specularIntensity: pipeline.specular.intensity,
          glossMin: pipeline.specular.glossMin,
          glossMax: pipeline.specular.glossMax,
        });
      }
      if (pipeline?.ao?.enabled) {
        await tryGenerate('ao', 'ao', { aoIntensity: pipeline.ao.strength ?? 0.5 });
      }
      if (pipeline?.height?.enabled) {
        await tryGenerate('height', 'height', {});
      }
      if (pipeline?.cavity?.enabled) {
        await tryGenerate('cavity', 'cavity', { cavityRadius: pipeline.cavity.radius, cavityStrength: pipeline.cavity.strength });
      }
      // Real DDS conversion (texconv.exe/nvcompress.exe) when requested —
      // every map above is generated as PNG; convert in place if the user
      // asked for .dds output rather than silently staying PNG.
      let note: string | undefined;
      if ((params.outputFormat === 'dds' || params.outputFormat === 'both') && Object.keys(outputs).length > 0) {
        const DDS_FORMAT_BY_MAP: Record<string, DdsTextureFormat> = {
          albedo: 'DDS_DXT1', normal: 'DDS_BC5', roughness: 'DDS_BC7', metallic: 'DDS_BC7', specular: 'DDS_BC7', ao: 'DDS_BC7', cavity: 'DDS_BC7', height: 'DDS_UNCOMPRESSED',
        };
        for (const [key, pngPath] of Object.entries(outputs)) {
          if (!pngPath.endsWith('.png')) continue;
          const ddsPath = pngPath.replace(/\.png$/, '.dds');
          const conv = await ddsConverter.convertTexture({ sourcePath: pngPath, outputPath: ddsPath, format: DDS_FORMAT_BY_MAP[key] || 'DDS_DXT1', generateMipmaps: true, quality: 'high' });
          if (conv.success) {
            if (params.outputFormat === 'dds') {
              try { fs.unlinkSync(pngPath); } catch { /* non-fatal */ }
              outputs[key] = ddsPath;
            } else {
              outputs[`${key}Dds`] = ddsPath;
            }
          } else {
            errors.push(`${key} DDS conversion: ${conv.error || 'failed'} — kept PNG output`);
          }
        }
      }

      return { success: Object.keys(outputs).length > 0, outputs, errors, note };
    } catch (error: any) {
      console.error('[Texture Enhancer] Error:', error);
      return { success: false, outputs: {}, errors: [], error: error?.message || String(error) };
    }
  };

  registerHandler('texture-enhancer:enhance', async (_event, params: {
    inputPath: string; outputFolder?: string; mode: string; surface: string; quality: string; outputFormat: string; pipeline: any;
  }) => {
    const { inputPath, outputFolder, mode } = params;
    if (!inputPath) {
      return { success: false, error: 'No input texture or folder selected.' };
    }

    if (mode !== 'batch') {
      return enhanceOneTexture(inputPath, outputFolder, params);
    }

    // Batch mode: run the real single-texture pipeline against every texture
    // file found directly inside the chosen folder (non-recursive).
    if (!fs.existsSync(inputPath) || !fs.statSync(inputPath).isDirectory()) {
      return { success: false, error: 'Batch folder not found on disk. Use "Pick texture folder" to choose a real folder.' };
    }
    const files = fs.readdirSync(inputPath)
      .filter((f) => TEXTURE_ENHANCER_EXTENSIONS.includes(path.extname(f).toLowerCase()))
      .map((f) => path.join(inputPath, f));

    if (files.length === 0) {
      return { success: false, error: `No texture files (${TEXTURE_ENHANCER_EXTENSIONS.join(', ')}) found in ${inputPath}.` };
    }

    const aggregatedOutputs: Record<string, string> = {};
    const aggregatedErrors: string[] = [];
    let successCount = 0;

    for (const filePath of files) {
      const fileBase = path.basename(filePath, path.extname(filePath));
      const result = await enhanceOneTexture(filePath, outputFolder, params);
      if (result.error) {
        aggregatedErrors.push(`${fileBase}: ${result.error}`);
        continue;
      }
      for (const [key, value] of Object.entries(result.outputs)) {
        aggregatedOutputs[`${fileBase}_${key}`] = value;
      }
      for (const err of result.errors) {
        aggregatedErrors.push(`${fileBase} — ${err}`);
      }
      if (result.success) successCount++;
    }

    return {
      success: successCount > 0,
      outputs: aggregatedOutputs,
      errors: aggregatedErrors,
      note: `Batch complete: ${successCount}/${files.length} texture(s) enhanced.`,
    };
  });

  // Texture Enhancer learning loop: record whether a job's output was kept or
  // discarded (with an optional 1-5 rating), fold "kept" jobs' numeric pipeline
  // settings into a persistent per-surface running average, and hand back the
  // current learned stats so the renderer can blend them into surface preset
  // defaults on future runs. See textureEnhancerLearning.ts for the aggregation.
  registerHandler('texture-enhancer:record-outcome', async (_event, params: {
    surface: string; pipeline: Record<string, any>; outcome: 'kept' | 'discarded'; rating?: number;
  }) => {
    try {
      if (!params?.surface || !params?.pipeline || (params.outcome !== 'kept' && params.outcome !== 'discarded')) {
        return { success: false, error: 'Missing surface, pipeline, or a valid outcome.' };
      }
      recordEnhancerOutcome(params);
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err?.message || String(err) };
    }
  });

  registerHandler('texture-enhancer:get-learned-stats', async () => {
    try {
      return { success: true, stats: getEnhancerLearnedStats() };
    } catch (err: any) {
      return { success: false, error: err?.message || String(err), stats: {} };
    }
  });

  registerHandler('texture-enhancer:reset-learning', async (_event, params?: { surface?: string }) => {
    try {
      resetEnhancerLearning(params?.surface);
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err?.message || String(err) };
    }
  });

  // Asset Validator Handlers
  registerHandler('asset-validator:validate-mod', async (event, modPath: string) => {
    try {
      const validation = IpcValidation.isValidFilePath(modPath);
      if (!validation.valid) return IpcResponseBuilder.error(validation.error ?? "Validation error", IpcErrorCode.EINVAL);
      if (!fs.existsSync(modPath)) {
        return IpcResponseBuilder.error('Mod path not found', IpcErrorCode.ENOENT);
      }

      const issues: any[] = [];
      let filesScanned = 0;
      let totalSize = 0;
      const fileTypes: Record<string, number> = {};
      const startTime = Date.now();
      let lastProgressSent = 0;

      // Scans recursively but yields to the event loop every 40 files so a large mod
      // (thousands of files, especially under real-time AV scanning which can add
      // significant per-file latency) never blocks the main process — and every other
      // IPC-backed feature in the app — for the full duration of the scan. Also emits
      // live progress so the renderer isn't stuck showing a static "Scanning…" spinner
      // with no feedback for minutes at a time.
      const scanDir = async (dir: string, depth = 0): Promise<void> => {
        if (depth > 8) return;
        try {
          const files = fs.readdirSync(dir);
          for (const file of files) {
            const filePath = path.join(dir, file);
            try {
              const stat = fs.statSync(filePath);
              if (stat.isDirectory()) {
                await scanDir(filePath, depth + 1);
              } else {
                filesScanned++;
                totalSize += stat.size;
                const ext = path.extname(file).toLowerCase();
                fileTypes[ext] = (fileTypes[ext] || 0) + 1;

                if (filesScanned - lastProgressSent >= 40) {
                  lastProgressSent = filesScanned;
                  try {
                    event.sender.send('asset-validator:scan-progress', {
                      modPath, filesScanned, elapsedMs: Date.now() - startTime,
                    });
                  } catch { /* window may have closed */ }
                  // Yield to the event loop so this scan never fully blocks the main
                  // process (and every other IPC-backed feature) for its whole duration.
                  await new Promise((resolve) => setImmediate(resolve));
                }

                // DDS texture validation
                if (ext === '.dds') {
                  if (stat.size > 500 * 1024 * 1024) {
                    issues.push({
                      id: `dds-${filesScanned}`,
                      file: filePath,
                      type: 'texture-size',
                      severity: 'error',
                      message: `DDS texture exceeds 500MB (${(stat.size / 1024 / 1024).toFixed(2)}MB)`,
                      autoFixable: false,
                    });
                  } else if (stat.size > 200 * 1024 * 1024) {
                    issues.push({
                      id: `dds-${filesScanned}`,
                      file: filePath,
                      type: 'texture-size',
                      severity: 'warning',
                      message: `DDS texture is large (${(stat.size / 1024 / 1024).toFixed(2)}MB)`,
                      autoFixable: false,
                    });
                  }
                }

                // ESP/ESM plugin validation
                if (ext === '.esp' || ext === '.esm' || ext === '.esl') {
                  if (stat.size < 100) {
                    issues.push({
                      id: `esp-${filesScanned}`,
                      file: filePath,
                      type: 'plugin-size',
                      severity: 'error',
                      message: 'Plugin file is suspiciously small (possibly empty)',
                      autoFixable: false,
                    });
                  }
                }

                // Filename validation
                if (file.includes(' ')) {
                  issues.push({
                    id: `filename-${filesScanned}`,
                    file: filePath,
                    type: 'filename-format',
                    severity: 'info',
                    message: 'File contains spaces (consider using underscores)',
                    autoFixable: true,
                  });
                }

                // NIF mesh validation
                if (ext === '.nif') {
                  if (stat.size > 50 * 1024 * 1024) {
                    issues.push({
                      id: `nif-${filesScanned}`,
                      file: filePath,
                      type: 'mesh-size',
                      severity: 'warning',
                      message: `NIF mesh is very large (${(stat.size / 1024 / 1024).toFixed(2)}MB)`,
                      autoFixable: false,
                    });
                  }
                }
              }
            } catch (err) {
              // Skip inaccessible files
            }
          }
        } catch (err) {
          console.error(`[Validator] Error scanning directory: ${dir}`, err);
        }
      };

      await scanDir(modPath);
      const scanTime = Date.now() - startTime;

      // Calculate compliance score
      const errorCount = issues.filter(i => i.severity === 'error').length;
      const warningCount = issues.filter(i => i.severity === 'warning').length;
      const infoCount = issues.filter(i => i.severity === 'info').length;

      let complianceScore = 100;
      complianceScore -= errorCount * 20;
      complianceScore -= warningCount * 5;
      complianceScore -= infoCount * 1;
      complianceScore = Math.max(0, Math.min(100, complianceScore));

      const report = {
        modPath,
        totalFiles: filesScanned,
        filesScanned,
        totalSize,
        totalSizeMB: (totalSize / 1024 / 1024).toFixed(2),
        fileTypes,
        issues,
        summary: {
          errors: errorCount,
          warnings: warningCount,
          info: infoCount,
        },
        scanTime,
        timestamp: Date.now(),
        compliance: {
          score: complianceScore,
          rating: complianceScore >= 90 ? 'Excellent' : complianceScore >= 70 ? 'Good' : complianceScore >= 50 ? 'Fair' : 'Poor',
          passedChecks: complianceScore === 100 ? ['structure', 'encoding', 'sizes', 'formats'] : ['basic-structure'],
          failedChecks: issues.map(i => i.type),
        },
      };
      return IpcResponseBuilder.success({ report });
    } catch (error) {
      console.error('[Asset Validator] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  registerHandler('asset-validator:validate-file', async (_event, filePath: string) => {
    try {
      const validation = IpcValidation.isValidFilePath(filePath);
      if (!validation.valid) return IpcResponseBuilder.error(validation.error ?? "Validation error", IpcErrorCode.EINVAL);
      if (!fs.existsSync(filePath)) {
        return IpcResponseBuilder.error('File not found', IpcErrorCode.ENOENT);
      }

      const stat = fs.statSync(filePath);
      const ext = path.extname(filePath).toLowerCase();
      const fileName = path.basename(filePath);
      const issues: any[] = [];

      // Empty file check
      if (stat.size === 0) {
        issues.push({
          id: 'empty',
          severity: 'error',
          message: 'File is empty',
          autoFixable: false,
        });
      }

      // DDS file validation
      if (ext === '.dds') {
        if (stat.size > 500 * 1024 * 1024) {
          issues.push({
            id: 'dds-too-large',
            severity: 'error',
            message: `Exceeds 500MB (${(stat.size / 1024 / 1024).toFixed(2)}MB)`,
            autoFixable: false,
          });
        } else if (stat.size > 200 * 1024 * 1024) {
          issues.push({
            id: 'dds-large',
            severity: 'warning',
            message: `Large file (${(stat.size / 1024 / 1024).toFixed(2)}MB)`,
            autoFixable: false,
          });
        }
      }

      // ESP/ESM validation
      if (ext === '.esp' || ext === '.esm' || ext === '.esl') {
        if (stat.size < 100) {
          issues.push({
            id: 'esp-small',
            severity: 'error',
            message: 'Plugin is suspiciously small',
            autoFixable: false,
          });
        }
      }

      // Filename validation
      if (fileName.includes(' ')) {
        issues.push({
          id: 'spaces',
          severity: 'info',
          message: 'Filename contains spaces',
          autoFixable: true,
        });
      }

      const hasErrors = issues.some(i => i.severity === 'error');
      let complianceScore = hasErrors ? 40 : 100;

      const report = {
        modPath: path.dirname(filePath),
        fileName,
        totalFiles: 1,
        filesScanned: 1,
        fileSize: stat.size,
        fileSizeMB: (stat.size / 1024 / 1024).toFixed(2),
        issues,
        summary: {
          errors: issues.filter(i => i.severity === 'error').length,
          warnings: issues.filter(i => i.severity === 'warning').length,
          info: issues.filter(i => i.severity === 'info').length,
        },
        scanTime: 1,
        timestamp: Date.now(),
        compliance: {
          score: complianceScore,
          rating: complianceScore >= 90 ? 'Excellent' : 'Has Issues',
          passedChecks: !hasErrors ? ['format', 'size', 'integrity'] : [],
          failedChecks: hasErrors ? ['integrity'] : [],
        },
      };
      return IpcResponseBuilder.success({ report });
    } catch (error) {
      console.error('[Asset Validator] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  registerHandler('asset-validator:auto-fix', async (_event, issues: any[]) => {
    try {
      if (!Array.isArray(issues)) {
        return IpcResponseBuilder.error('Issues payload must be an array', IpcErrorCode.EINVAL);
      }

      const applied: Array<{ id?: string; file: string; action: string }> = [];
      const failed: Array<{ id?: string; file?: string; error: string }> = [];

      for (const issue of issues) {
        try {
          if (!issue || typeof issue !== 'object') continue;
          const filePath = String(issue.file || '');
          if (!filePath) continue;

          if (issue.type === 'filename-format' && issue.autoFixable === true) {
            if (!fs.existsSync(filePath)) {
              failed.push({ id: issue.id, file: filePath, error: 'File no longer exists' });
              continue;
            }

            const dir = path.dirname(filePath);
            const base = path.basename(filePath);
            const normalized = base.replace(/\s+/g, '_');

            if (!normalized || normalized === base) continue;

            const targetPath = path.join(dir, normalized);
            if (fs.existsSync(targetPath)) {
              failed.push({ id: issue.id, file: filePath, error: `Target exists: ${targetPath}` });
              continue;
            }

            fs.renameSync(filePath, targetPath);
            applied.push({ id: issue.id, file: targetPath, action: 'renamed-spaces-to-underscores' });
          }
        } catch (err: any) {
          failed.push({ id: issue?.id, file: issue?.file, error: String(err?.message || err) });
        }
      }

      return IpcResponseBuilder.success({
        appliedCount: applied.length,
        failedCount: failed.length,
        applied,
        failed,
      });
    } catch (error) {
      console.error('[Asset Validator auto-fix] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  // Image Processing Handlers
  registerHandler('image-suite:generate-pbr', async (_event, params: any) => {
    try {
      const { sourceImagePath, mapsToGenerate = ['normal', 'roughness', 'metallic', 'height', 'ao'] } = params;
      const validation = IpcValidation.isValidFilePath(sourceImagePath);
      if (!validation.valid) return IpcResponseBuilder.error(validation.error ?? "Validation error", IpcErrorCode.EINVAL);
      if (!fs.existsSync(sourceImagePath)) {
        return IpcResponseBuilder.error('Source image not found', IpcErrorCode.ENOENT);
      }

      const sharp = (await import('sharp')).default;
      const outputDir = path.join(path.dirname(sourceImagePath), 'pbr_maps');
      if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
      }

      const baseName = path.basename(sourceImagePath, path.extname(sourceImagePath));
      const results: any = {};

      // Load source image metadata
      const img = sharp(sourceImagePath);
      const metadata = await img.metadata();
      const { width = 1024, height = 1024 } = metadata;

      // Generate Normal Map (edge detection via grayscale + normalize)
      if (mapsToGenerate.includes('normal')) {
        const normalPath = path.join(outputDir, `${baseName}_normal.png`);
        await sharp(sourceImagePath)
          .resize(width, height, { fit: 'fill' })
          .greyscale()
          .normalize()
          .toFile(normalPath);
        results.normal = normalPath;
      }

      // Generate Roughness Map (luminance-based)
      if (mapsToGenerate.includes('roughness')) {
        const roughPath = path.join(outputDir, `${baseName}_roughness.png`);
        await sharp(sourceImagePath)
          .resize(width, height, { fit: 'fill' })
          .greyscale()
          .modulate({ saturation: 0.5 })
          .toFile(roughPath);
        results.roughness = roughPath;
      }

      // Generate Metallic Map (from highlights)
      if (mapsToGenerate.includes('metallic')) {
        const metallicPath = path.join(outputDir, `${baseName}_metallic.png`);
        await sharp(sourceImagePath)
          .resize(width, height, { fit: 'fill' })
          .greyscale()
          .linear(1.2, 10)
          .toFile(metallicPath);
        results.metallic = metallicPath;
      }

      // Generate Height Map (grayscale conversion with adjustments)
      if (mapsToGenerate.includes('height')) {
        const heightPath = path.join(outputDir, `${baseName}_height.png`);
        await sharp(sourceImagePath)
          .resize(width, height, { fit: 'fill' })
          .greyscale()
          .normalize()
          .toFile(heightPath);
        results.height = heightPath;
      }

      // Generate Ambient Occlusion Map (darkened grayscale)
      if (mapsToGenerate.includes('ao')) {
        const aoPath = path.join(outputDir, `${baseName}_ao.png`);
        await sharp(sourceImagePath)
          .resize(width, height, { fit: 'fill' })
          .greyscale()
          .linear(0.7, 20)
          .toFile(aoPath);
        results.ao = aoPath;
      }

      console.log('[Image Suite PBR] Generated PBR maps:', results);
      return IpcResponseBuilder.success({
        ...results,
        status: 'complete',
        outputDir,
        mapsGenerated: Object.keys(results),
      });
    } catch (error) {
      console.error('[Image Suite PBR] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.OPERATION_FAILED);
    }
  });

  registerHandler('image-suite:convert-format', async (_event, params: any) => {
    try {
      const { inputPath, outputPath, format, quality = 80, resize } = params;
      const inputValidation = IpcValidation.isValidFilePath(inputPath);
      if (!inputValidation.valid) return IpcResponseBuilder.error(inputValidation.error ?? "Validation error", IpcErrorCode.EINVAL);
      const outputValidation = IpcValidation.isValidFilePath(outputPath);
      if (!outputValidation.valid) return IpcResponseBuilder.error(outputValidation.error ?? "Validation error", IpcErrorCode.EINVAL);
      if (!fs.existsSync(inputPath)) {
        return IpcResponseBuilder.error('Input file not found', IpcErrorCode.ENOENT);
      }

      const outputDir = path.dirname(outputPath);
      if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
      }

      const sharp = (await import('sharp')).default;
      let pipeline = sharp(inputPath);

      // Apply resize if specified
      if (resize && (resize.width || resize.height)) {
        pipeline = pipeline.resize(resize.width || resize.height, resize.height || resize.width, { 
          fit: 'inside',
          withoutEnlargement: true 
        });
      }

      // Convert to target format with quality settings
      const formatLower = format.toLowerCase();
      if (formatLower === 'jpg' || formatLower === 'jpeg') {
        pipeline = pipeline.jpeg({ quality, progressive: true });
      } else if (formatLower === 'png') {
        pipeline = pipeline.png({ compressionLevel: 9 });
      } else if (formatLower === 'webp') {
        pipeline = pipeline.webp({ quality });
      } else if (formatLower === 'bmp') {
        // BMP: output as PNG (compatible with Fallout 4 tools)
        pipeline = pipeline.png({ compressionLevel: 6 });
      } else if (formatLower === 'tga' || formatLower === 'targa') {
        // TGA via PNG fallback (Sharp doesn't native TGA, but we can convert to PNG for Fallout 4 tools)
        pipeline = pipeline.png();
      } else if (formatLower === 'dds') {
        // DDS is handled separately, but we'll convert to PNG as intermediate
        pipeline = pipeline.png();
      } else {
        pipeline = pipeline.png(); // Default to PNG
      }

      await pipeline.toFile(outputPath);
      const stat = fs.statSync(outputPath);
      
      console.log(`[Image Suite Convert] Converted: ${inputPath} → ${outputPath} (${format}, ${stat.size} bytes)`);
      return IpcResponseBuilder.success({
        filePath: outputPath,
        format: format,
        size: stat.size,
        originalSize: fs.statSync(inputPath).size,
        compressionRatio: ((1 - (stat.size / fs.statSync(inputPath).size)) * 100).toFixed(2) + '%',
      });
    } catch (error) {
      console.error('[Image Suite Convert] Error:', error);
      return IpcResponseBuilder.fromError(error, IpcErrorCode.CONVERSION_FAILED);
    }
  });

  // Asset Optimizer Handlers
